$jiJars = @(Get-ChildItem -Path 'ji-java' -Recurse -File -Filter '*-0.1.0-SNAPSHOT.jar' | Where-Object { $_.FullName -match '[\\/]build[\\/]libs[\\/]' -and $_.Name -notmatch '-(sources|javadoc)\.jar$' } | Select-Object -ExpandProperty FullName); $jacksonJars = @(Get-ChildItem -Path (Join-Path $env:USERPROFILE '.gradle\caches\modules-2\files-2.1\com.fasterxml.jackson.core') -Recurse -File -Filter '*.jar' | Select-Object -ExpandProperty FullName); $probeCp = (@($jiJars + $jacksonJars) | Sort-Object -Unique) -join ';'; @'
import io.github.diodeme.ji.agent.*;
import io.github.diodeme.ji.ai.*;
import io.github.diodeme.ji.host.*;
import io.github.diodeme.ji.session.*;
import io.github.diodeme.ji.testkit.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.lang.reflect.*;
import java.security.*;
var base = new MemoryHostStore();
var store = (HostStore) Proxy.newProxyInstance(HostStore.class.getClassLoader(), new Class<?>[]{HostStore.class}, (proxy, method, arguments) -> { if (method.getName().equals("finishRun")) throw new IllegalStateException("injected_terminal_commit_failure"); try { return method.invoke(base, arguments); } catch (InvocationTargetException failure) { throw failure.getCause(); } });
var provider = new ScriptedModelProvider().enqueue(List.of(new ScriptedModelProvider.Step.Text("done"), new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
var permissions = new PermissionBroker(Clock.systemUTC());
var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(store).permissionDecider(permissions).build(); var sessions = new SessionApplicationService(runtime);
var sessionId = sessions.create(new ModelRef("faux", "faux-1"), ".").id(); var prompts = new PromptApplicationService(sessions, store);
var accepted = prompts.prompt(sessionId, "command-terminal", "hello");
try { accepted.run().orElseThrow().completion().toCompletableFuture().get(1, TimeUnit.SECONDS); System.out.println("TERMINAL_FAILURE_COMPLETION=settled"); } catch (Throwable failure) { System.out.println("TERMINAL_FAILURE_COMPLETION=" + failure.getClass().getSimpleName()); }
var hash = java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest("hello".getBytes(java.nio.charset.StandardCharsets.UTF_8)));
var record = store.command(sessionId, "command-terminal", hash);
System.out.println("TERMINAL_FAILURE_JOURNAL=" + record.map(value -> value.status().name()).orElse("absent"));
System.out.println("TERMINAL_FAILURE_ACTIVE=" + sessions.hasActiveRun(sessionId));
sessions.close();
var normalProvider = new ScriptedModelProvider(); var normalStore = new io.github.diodeme.ji.session.memory.MemorySessionStore();
var closedRuntime = new AgentRuntimeBuilder().provider(normalProvider).sessionStore(normalStore).build(); closedRuntime.close();
try { closedRuntime.newSession(new SessionOptions(new ModelRef("faux", "faux-1"), ".")); System.out.println("CLOSED_RUNTIME=accepted"); } catch (Throwable failure) { System.out.println("CLOSED_RUNTIME=" + failure.getClass().getName() + ":" + failure.getMessage()); }
var closedOpenAi = io.github.diodeme.ji.provider.openai.OpenAiProvider.builder().baseUrl("http://127.0.0.1:1").build(); closedOpenAi.close();
var cancel = new io.github.diodeme.ji.ai.CancellationSource();
var request = new ModelRequest("session-1", new ModelRef("openai", "model"), "", List.of(), List.of(), Map.of(), cancel.token());
try { closedOpenAi.stream(request); System.out.println("CLOSED_PROVIDER=accepted"); } catch (Throwable failure) { System.out.println("CLOSED_PROVIDER=" + failure.getClass().getName() + ":" + failure.getMessage()); }
/exit
'@ | jshell --class-path $probeCp
